write('com/shilapi/xcertplay/DirectCheck.java','''package com.shilapi.xcertplay;import android.content.Context;import android.os.SystemClock;import java.util.*;public class DirectCheck{static int n;static void ck(boolean b){n++;if(!b)throw new AssertionError(n+" "+E01PrivilegedShell.output);}static void reset(){SystemClock.now+=10000;E01PrivilegedShell.output.clear();E01PrivilegedShell.fail=false;E01PrivilegedShell.lost=false;E01PrivilegedShell.pauseFail=false;E01PrivilegedShell.restoreFail=false;E01PrivilegedShell.old=false;android.content.pm.PackageManager.version=21000001;android.content.pm.PackageManager.missing=false;}static void advance(){SystemClock.now+=4000;}public static void main(String[] args){reset();Context c=new Context();E01AmapOutput o=new E01AmapOutput();ck(o.ensure(c));ck(E01PrivilegedShell.output.equals(Arrays.asList(0)));int calls=E01PrivilegedShell.calls;for(int i=0;i<100;i++)ck(o.ensure(c));ck(calls==E01PrivilegedShell.calls);ck(o.finish(c));ck(E01PrivilegedShell.output.equals(Arrays.asList(0,1)));calls=E01PrivilegedShell.calls;for(int i=0;i<100;i++)ck(o.finish(c));ck(calls==E01PrivilegedShell.calls);reset();c=new Context();o=new E01AmapOutput();ck(o.ensure(c));E01AmapOutput reopened=new E01AmapOutput();ck(reopened.finish(c));ck(E01PrivilegedShell.output.equals(Arrays.asList(0,1)));reset();c=new Context();o=new E01AmapOutput();E01PrivilegedShell.lost=true;ck(!o.ensure(c));advance();ck(o.ensure(c));ck(E01PrivilegedShell.output.equals(Arrays.asList(0,1,0)));ck(o.finish(c));reset();c=new Context();o=new E01AmapOutput();ck(o.ensure(c));E01PrivilegedShell.restoreFail=true;ck(!o.finish(c));ck(c.prefs.getBoolean("restore_output",false));E01PrivilegedShell.restoreFail=false;advance();ck(o.finish(c));ck(!c.prefs.getBoolean("restore_output",false));reset();c=new Context();c.prefs.fail=true;o=new E01AmapOutput();ck(!o.ensure(c));ck(E01PrivilegedShell.output.isEmpty());reset();c=new Context();o=new E01AmapOutput();E01PrivilegedShell.fail=true;ck(!o.ensure(c));ck(E01PrivilegedShell.output.isEmpty());reset();c=new Context();o=new E01AmapOutput();android.content.pm.PackageManager.version=1;ck(!o.ensure(c));ck(E01PrivilegedShell.output.isEmpty());reset();c=new Context();o=new E01AmapOutput();E01PrivilegedShell.old=true;ck(o.ensure(c));ck(E01PrivilegedShell.legacyKills>0&&E01PrivilegedShell.output.equals(Arrays.asList(1,0)));ck(o.finish(c));reset();c=new Context();o=new E01AmapOutput();android.content.pm.PackageManager.missing=true;ck(o.ensure(c));ck(E01PrivilegedShell.output.isEmpty());System.out.println("PASS "+n+" direct-output state checks; fake OEM service, no watchdog/ADB test dependencies");}}''')
